/* Test 63: the float to integer conversion routines, __fixsfdi, __fixunssfdi,
   __fixsfti and __fixunssfti. Each row is an input and the four answers it
   should give: truncation toward zero, zero for a NaN or for a negative value
   asked for as unsigned, and saturation to the limit of the type otherwise.
   Out-of-range inputs are undefined in C and the host answers them
   differently, so the host oracle is not asked. Returns 0xFFFF when every row
   agrees, otherwise the one-based number of the first row that did not.
   NATIVE-SKIP  expect 0xFFFF */
typedef unsigned short uint16_t;
typedef unsigned long uint32_t;
typedef long long i64;
typedef unsigned long long u64;
typedef __int128 i128;
typedef unsigned __int128 u128;
typedef union { float f; uint32_t u; } f32u;

static float mk(uint32_t u) { f32u x; x.u = u; return x.f; }

struct row {
    uint32_t in;
    u64 sdi, udi;
    u64 sti_hi, sti_lo, uti_hi, uti_lo;
};

